
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_beefvdw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_beefvdw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.416128592093982e+00, -4.331821050830913e+00, -4.213910325297793e+00, -4.051050791800070e+00, -3.830136448995727e+00, -3.538186056389157e+00, -3.166694511472059e+00, -2.720415014116035e+00, -2.221929623501563e+00, -1.695175884458547e+00, -1.165564394507529e+00, -7.319541554074029e-01, -6.190204243451854e-01, -5.152703993469205e-01, -3.871328441739302e-01, -2.628699821001901e-01, -1.447414452590826e-01, -5.166804996272331e-02, -1.121002463869135e-02, -1.260587719247288e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


